      x: cx3 + 0.7, y: cardY + 0.2, w: 1.9, h: 0.35,
      fontSize: 14, fontFace: "Calibri", color: C.darkText, bold: true, margin: 0
    });
    slide.addText("e.g., KnowAgent, WKM", {
      x: cx3 + 0.7, y: cardY + 0.48, w: 1.9, h: 0.25,
      fontSize: 10, fontFace: "Calibri", color: C.mutedText, margin: 0
    });
    slide.addText([
      { text: "Injects domain knowledge at every step — even when the agent could act correctly on its own.", options: { breakLine: true, fontSize: 11, color: C.darkText } },
      { text: "", options: { breakLine: true, fontSize: 6 } },
      { text: "Leads to:", options: { breakLine: true, fontSize: 11, color: C.mutedText, bold: true } },
      { text: "High knowledge retrieval costs", options: { bullet: true, fontSize: 10, color: C.red } },
      { text: "Knowledge interference on simple steps", options: { bullet: true, fontSize: 10, color: C.red } }
    ], { x: cx3 + 0.2, y: cardY + 0.9, w: cardW - 0.4, h: 1.4, valign: "top", margin: 0 });

    // Bottom callout
    slide.addShape(pres.shapes.RECTANGLE, {
      x: 0.6, y: 4.5, w: 8.8, h: 0.75,
      fill: { color: C.darkBg }, rectRadius: 0.08
    });
