      bold: true, align: "center", valign: "middle", margin: 0
    });

    // Arrow down
    slide.addShape(pres.shapes.LINE, {
      x: flowCenterX, y: 1.7, w: 0, h: 0.25,
      line: { color: C.mutedText, width: 2 }
    });

    // Diamond: "Predicted action matches gold?"
    const dmW = 3.2;
    const dmH = 0.55;
    slide.addShape(pres.shapes.RECTANGLE, {
      x: flowCenterX - dmW / 2, y: 1.95, w: dmW, h: dmH,
