        labels: ["ExpeL\n(GPT-4o)", "ExpeL\n(Llama-8B)", "KnowAgent\n(Llama-8B)", "WKM\n(Llama-8B)", "KnowSelf\n(Llama-8B)", "KnowAgent\n(Gemma-2B)", "WKM\n(Gemma-2B)", "KnowSelf\n(Gemma-2B)"],
        values: [79.85, 41.04, 75.37, 77.61, 84.33, 73.88, 76.12, 79.85]
      }
    ];

    slide.addChart(pres.charts.BAR, chartData2, {
      x: 5.3, y: 1.05, w: 4.5, h: 3.2,
      barDir: "col",
      showTitle: true,
      title: "Overall Accuracy (%)",
      titleColor: C.darkText,
      titleFontSize: 12,
      chartColors: [C.mutedText, C.mutedText, C.mutedText, C.mutedText, C.skyBlue, C.mutedText, C.mutedText, C.skyBlue],
      chartArea: { fill: { color: C.cardWhite }, roundedCorners: true },
      catAxisLabelColor: C.mutedText,
      catAxisLabelFontSize: 8,
      valAxisLabelColor: C.mutedText,
      valAxisLabelFontSize: 8,
      valAxisMinVal: 0,
      valAxisMaxVal: 100,
      valGridLine: { color: C.lightBorder, size: 0.5 },
      catGridLine: { style: "none" },
      showValue: true,
      dataLabelPosition: "outEnd",
      dataLabelColor: C.darkText,
      dataLabelFontSize: 8,
      showLegend: false,
    });

    // Bottom insight boxes
    const boxY = 4.4;
    const boxH = 0.95;
    const boxW = 4.4;

    // Box 1: Llama-8B comparison
    slide.addShape(pres.shapes.RECTANGLE, {
      x: 0.4, y: boxY, w: boxW, h: boxH,
      fill: { color: C.cardWhite }, shadow: makeCardShadow()
    });
    slide.addShape(pres.shapes.RECTANGLE, {
      x: 0.4, y: boxY, w: 0.06, h: boxH, fill: { color: C.skyBlue }
    });
    slide.addText([
      { text: "Llama-8B: 15% knowledge → 84.33%", options: { breakLine: true, fontSize: 13, fontFace: "Calibri", color: C.skyBlue, bold: true } },
      { text: "vs. KnowAgent 100% → 75.37% | WKM 100% → 77.61%", options: { breakLine: true, fontSize: 10, color: C.darkText } },
      { text: "6–9 points higher with ~85% less knowledge", options: { fontSize: 10, color: C.mutedText, italic: true } }
    ], { x: 0.6, y: boxY + 0.05, w: boxW - 0.3, h: boxH - 0.1, valign: "top", margin: 0 });

    // Box 2: Gemma-2B comparison
    slide.addShape(pres.shapes.RECTANGLE, {
      x: 5.2, y: boxY, w: boxW, h: boxH,
      fill: { color: C.cardWhite }, shadow: makeCardShadow()
    });
    slide.addShape(pres.shapes.RECTANGLE, {
      x: 5.2, y: boxY, w: 0.06, h: boxH, fill: { color: C.violet }
    });
    slide.addText([
      { text: "Gemma-2B: 26% knowledge → 79.85%", options: { breakLine: true, fontSize: 13, fontFace: "Calibri", color: C.violet, bold: true } },
      { text: "Matches GPT-4o ExpeL (79.85%) — a model 4× its size", options: { breakLine: true, fontSize: 10, color: C.darkText } },
      { text: "Self-awareness generalizes across model scales", options: { fontSize: 10, color: C.mutedText, italic: true } }
    ], { x: 5.4, y: boxY + 0.05, w: boxW - 0.3, h: boxH - 0.1, valign: "top", margin: 0 });
  }

  // ========================================================
  // SLIDE 8: Key Takeaways
  // ========================================================
  {
    const slide = pres.addSlide();
    slide.background = { color: C.darkBg };

    // Top accent line
    slide.addShape(pres.shapes.RECTANGLE, {
      x: 0, y: 0, w: 10, h: 0.06, fill: { color: C.skyBlue }
    });

    // Title
    slide.addText("Key Takeaways", {
      x: 0.8, y: 0.3, w: 8, h: 0.6,
      fontSize: 32, fontFace: "Arial Black", color: C.whiteText,
      bold: true, margin: 0
    });
    slide.addText("Self-Awareness Is the Missing Piece in Agent Planning", {
      x: 0.8, y: 0.82, w: 8, h: 0.35,
      fontSize: 14, fontFace: "Calibri", color: C.skyBlue, italic: true, margin: 0
    });

    // Five takeaway cards
    const takeaways = [
      { num: "1", color: C.red, text: "Indiscriminate knowledge injection is wasteful and suboptimal — flood-irrigation approaches hurt agent efficiency and performance." },
      { num: "2", color: C.skyBlue, text: "Agents can learn situational self-awareness via special tokens with lightweight heuristic labeling on self-explored trajectories." },
      { num: "3", color: C.violet, text: "KnowSelf (Llama-8B) outperforms GPT-4o ReAct (84.33% vs 76.12%) and GPT-4o ExpeL (79.85%) on ALFWorld." },
      { num: "4", color: C.orange, text: "Only 15–26% knowledge usage needed versus 100% for competing methods — selective access outperforms blanket application." },
      { num: "5", color: C.green, text: "The paradigm generalizes across model scales — even Gemma-2B reaches 79.85%, matching GPT-4o ExpeL." },
    ];

    const startY = 1.35;
    const cardH = 0.72;
    const cardGap = 0.12;
    const cardX = 0.8;
    const cardW = 8.4;

    takeaways.forEach((t, i) => {
      const cy = startY + i * (cardH + cardGap);

      // Card background
      slide.addShape(pres.shapes.RECTANGLE, {
        x: cardX, y: cy, w: cardW, h: cardH,
        fill: { color: C.darkBg2 }
      });

      // Left accent bar
      slide.addShape(pres.shapes.RECTANGLE, {
        x: cardX, y: cy, w: 0.06, h: cardH, fill: { color: t.color }
      });

      // Number badge
      slide.addShape(pres.shapes.OVAL, {
        x: cardX + 0.2, y: cy + 0.16, w: 0.4, h: 0.4,
        fill: { color: t.color }
      });
      slide.addText(t.num, {
        x: cardX + 0.2, y: cy + 0.16, w: 0.4, h: 0.4,
        fontSize: 16, fontFace: "Arial Black", color: C.whiteText,
        align: "center", valign: "middle", margin: 0
      });

      // Text
      slide.addText(t.text, {
        x: cardX + 0.75, y: cy + 0.05, w: cardW - 1.0, h: cardH - 0.1,
        fontSize: 12, fontFace: "Calibri", color: "CBD5E1",
        valign: "middle", margin: 0
      });
    });

    // Bottom reference
    slide.addText("arxiv.org/abs/2504.03553", {
      x: 0.8, y: 5.1, w: 4, h: 0.3,
      fontSize: 10, fontFace: "Calibri", color: "475569", margin: 0
    });
  }

  // --- Write file ---
  await pres.writeFile({ fileName: "/app/output/final_deck.pptx" });
  console.log("Presentation saved to /app/output/final_deck.pptx");
}

main().catch(err => {
  console.error("Error:", err);
  process.exit(1);
});

