const pptxgen = require("pptxgenjs");
const React = require("react");
const ReactDOMServer = require("react-dom/server");
const sharp = require("sharp");
const fs = require("fs");

function renderIconSvg(IconComponent, color = "#000000", size = 256) {
  return ReactDOMServer.renderToStaticMarkup(
    React.createElement(IconComponent, { color, size: String(size) })
  );
}

async function iconToBase64Png(IconComponent, color, size = 256) {
  const svg = renderIconSvg(IconComponent, color, size);
  const pngBuffer = await sharp(Buffer.from(svg)).png().toBuffer();
  return "image/png;base64," + pngBuffer.toString("base64");
}

async function main() {
  const { FaBolt, FaBrain, FaBook, FaArrowRight, FaExclamationTriangle, FaCheck, FaTimes, FaLightbulb, FaChartBar, FaRocket, FaBalanceScale, FaCog } = require("react-icons/fa");

  const iconBolt = await iconToBase64Png(FaBolt, "#0EA5E9", 256);
  const iconBrain = await iconToBase64Png(FaBrain, "#8B5CF6", 256);
  const iconBook = await iconToBase64Png(FaBook, "#F97316", 256);
  const iconArrow = await iconToBase64Png(FaArrowRight, "#94A3B8", 256);
  const iconWarning = await iconToBase64Png(FaExclamationTriangle, "#F97316", 256);
  const iconCog = await iconToBase64Png(FaCog, "#64748B", 256);

  const fig1Data = "image/jpeg;base64," + fs.readFileSync("/app/benchmark/assets/figure_1.jpg").toString("base64");

  const C = {
    darkBg: "0F172A", darkBg2: "1E293B", lightBg: "F1F5F9",
    cardWhite: "FFFFFF", skyBlue: "0EA5E9", violet: "8B5CF6",
    orange: "F97316", amber: "F59E0B", green: "10B981", red: "EF4444",
    darkText: "1E293B", mutedText: "64748B", whiteText: "FFFFFF",
    lightBorder: "E2E8F0", tableStripe: "F8FAFC",
  };

  const makeShadow = () => ({ type: "outer", blur: 8, offset: 2, angle: 135, color: "000000", opacity: 0.10 });

  const pres = new pptxgen();
  pres.layout = "LAYOUT_16x9";
  pres.author = "KnowSelf Research";
  pres.title = "KnowSelf: Teaching LLM Agents When to Think, Reflect, or Seek Knowledge";

  // ========================================================
  // SLIDE 1: Title
  // ========================================================
  {
    const slide = pres.addSlide();
    slide.background = { color: C.darkBg };

    slide.addShape(pres.shapes.RECTANGLE, {
      x: 0, y: 0, w: 10, h: 0.06, fill: { color: C.skyBlue }
    });

    // Decorative circles (clipped to slide)
    slide.addShape(pres.shapes.OVAL, {
      x: 8.0, y: 0.3, w: 2.0, h: 2.0,
      fill: { color: C.skyBlue, transparency: 92 }
    });
    slide.addShape(pres.shapes.OVAL, {
      x: -0.5, y: 3.5, w: 1.5, h: 1.5,
      fill: { color: C.violet, transparency: 93 }
    });

    // Three mode dots
    slide.addShape(pres.shapes.OVAL, { x: 3.8, y: 1.3, w: 0.18, h: 0.18, fill: { color: C.skyBlue } });
    slide.addShape(pres.shapes.OVAL, { x: 4.15, y: 1.3, w: 0.18, h: 0.18, fill: { color: C.violet } });
    slide.addShape(pres.shapes.OVAL, { x: 4.5, y: 1.3, w: 0.18, h: 0.18, fill: { color: C.orange } });

    slide.addText("KnowSelf", {
      x: 0.8, y: 1.55, w: 8.4, h: 0.85,
      fontSize: 44, fontFace: "Arial Black", color: C.whiteText, bold: true, margin: 0
    });

    slide.addText("Teaching LLM Agents When to Think, Reflect,\nor Seek Knowledge", {
      x: 0.8, y: 2.35, w: 8.4, h: 0.75,
      fontSize: 22, fontFace: "Calibri", color: C.skyBlue, margin: 0
    });

    slide.addText("Agentic Knowledgeable Self-Awareness for LLM-Based Agents", {
      x: 0.8, y: 3.3, w: 8.4, h: 0.45,
      fontSize: 14, fontFace: "Calibri", color: "94A3B8", italic: true, margin: 0
    });

    slide.addText("arxiv.org/abs/2504.03553", {
      x: 0.8, y: 4.6, w: 4, h: 0.35,
      fontSize: 12, fontFace: "Calibri", color: "64748B", margin: 0
    });

    // Bottom bar — keep within slide bounds
    slide.addShape(pres.shapes.RECTANGLE, {
      x: 0, y: 5.36, w: 10, h: 0.225, fill: { color: C.darkBg2 }
    });
  }

  // ========================================================
  // SLIDE 2: Problem — Flood Irrigation
  // ========================================================
  {
    const slide = pres.addSlide();
    slide.background = { color: C.lightBg };

    slide.addShape(pres.shapes.RECTANGLE, {
      x: 0, y: 0, w: 10, h: 0.9, fill: { color: C.darkBg }
    });
    slide.addText("Current Agent Training Uses 'Flood Irrigation'", {
      x: 0.6, y: 0.12, w: 7, h: 0.65,
      fontSize: 24, fontFace: "Arial Black", color: C.whiteText, bold: true, margin: 0
    });
    slide.addText("Indiscriminate Knowledge Injection Hurts Efficiency", {
      x: 0.6, y: 0.52, w: 7, h: 0.35,
      fontSize: 12, fontFace: "Calibri", color: C.skyBlue, margin: 0
    });
    slide.addImage({ data: iconWarning, x: 9.1, y: 0.18, w: 0.5, h: 0.5 });

    slide.addText("Existing methods inject gold trajectories, external feedback, or domain knowledge at every step — regardless of whether the agent actually needs them.", {
      x: 0.6, y: 1.1, w: 8.8, h: 0.5,
      fontSize: 13, fontFace: "Calibri", color: C.darkText, margin: 0
    });

    // Three cards — adjusted for 0.5" margins
    const cardW = 2.7;
    const cardH = 2.3;
    const gap = 0.35;
    const totalW = 3 * cardW + 2 * gap;
    const startX = (10 - totalW) / 2;
    const cardY = 1.75;

    // Card 1: Trajectory Imitation
    const cx1 = startX;
    slide.addShape(pres.shapes.RECTANGLE, { x: cx1, y: cardY, w: cardW, h: cardH, fill: { color: C.cardWhite }, shadow: makeShadow() });
    slide.addShape(pres.shapes.RECTANGLE, { x: cx1, y: cardY, w: cardW, h: 0.06, fill: { color: C.skyBlue } });
    slide.addImage({ data: iconCog, x: cx1 + 0.15, y: cardY + 0.15, w: 0.35, h: 0.35 });
    slide.addText("Trajectory Imitation", {
      x: cx1 + 0.55, y: cardY + 0.17, w: 2.0, h: 0.3,
      fontSize: 13, fontFace: "Calibri", color: C.darkText, bold: true, margin: 0
    });
    slide.addText("e.g., ReAct", {
      x: cx1 + 0.55, y: cardY + 0.42, w: 2.0, h: 0.2,
      fontSize: 10, fontFace: "Calibri", color: C.mutedText, margin: 0
    });
    slide.addText([
      { text: "Blindly imitates gold action sequences without understanding when actions are needed.", options: { breakLine: true, fontSize: 10, color: C.darkText } },
      { text: "", options: { breakLine: true, fontSize: 4 } },
      { text: "Fragile planning on unexpected inputs", options: { bullet: true, fontSize: 10, color: C.red } },
      { text: "Pattern collapse under distribution shift", options: { bullet: true, fontSize: 10, color: C.red } }
    ], { x: cx1 + 0.15, y: cardY + 0.7, w: cardW - 0.3, h: 1.5, valign: "top", margin: 0 });

    // Card 2: Trial-and-Error
    const cx2 = startX + cardW + gap;
    slide.addShape(pres.shapes.RECTANGLE, { x: cx2, y: cardY, w: cardW, h: cardH, fill: { color: C.cardWhite }, shadow: makeShadow() });
    slide.addShape(pres.shapes.RECTANGLE, { x: cx2, y: cardY, w: cardW, h: 0.06, fill: { color: C.violet } });
    slide.addImage({ data: iconBrain, x: cx2 + 0.15, y: cardY + 0.15, w: 0.35, h: 0.35 });
    slide.addText("Trial-and-Error Refinement", {
      x: cx2 + 0.55, y: cardY + 0.17, w: 2.0, h: 0.3,
      fontSize: 13, fontFace: "Calibri", color: C.darkText, bold: true, margin: 0
    });
    slide.addText("e.g., Reflexion", {
      x: cx2 + 0.55, y: cardY + 0.42, w: 2.0, h: 0.2,
      fontSize: 10, fontFace: "Calibri", color: C.mutedText, margin: 0
    });
    slide.addText([
      { text: "Applies feedback at every step, even when the agent already knows the correct action.", options: { breakLine: true, fontSize: 10, color: C.darkText } },
      { text: "", options: { breakLine: true, fontSize: 4 } },
      { text: "Unnecessary inference overhead", options: { bullet: true, fontSize: 10, color: C.red } },
      { text: "Over-correction of correct steps", options: { bullet: true, fontSize: 10, color: C.red } }
    ], { x: cx2 + 0.15, y: cardY + 0.7, w: cardW - 0.3, h: 1.5, valign: "top", margin: 0 });

    // Card 3: Knowledge-Augmented
    const cx3 = startX + 2 * (cardW + gap);
    slide.addShape(pres.shapes.RECTANGLE, { x: cx3, y: cardY, w: cardW, h: cardH, fill: { color: C.cardWhite }, shadow: makeShadow() });
    slide.addShape(pres.shapes.RECTANGLE, { x: cx3, y: cardY, w: cardW, h: 0.06, fill: { color: C.orange } });
    slide.addImage({ data: iconBook, x: cx3 + 0.15, y: cardY + 0.15, w: 0.35, h: 0.35 });
    slide.addText("Knowledge-Augmented", {
      x: cx3 + 0.55, y: cardY + 0.17, w: 2.0, h: 0.3,
      fontSize: 13, fontFace: "Calibri", color: C.darkText, bold: true, margin: 0
    });
    slide.addText("e.g., KnowAgent, WKM", {
      x: cx3 + 0.55, y: cardY + 0.42, w: 2.0, h: 0.2,
      fontSize: 10, fontFace: "Calibri", color: C.mutedText, margin: 0
    });
    slide.addText([
      { text: "Injects domain knowledge at every step, even when the agent could act correctly on its own.", options: { breakLine: true, fontSize: 10, color: C.darkText } },
      { text: "", options: { breakLine: true, fontSize: 4 } },
      { text: "High knowledge retrieval costs", options: { bullet: true, fontSize: 10, color: C.red } },
      { text: "Knowledge interference on simple steps", options: { bullet: true, fontSize: 10, color: C.red } }
    ], { x: cx3 + 0.15, y: cardY + 0.7, w: cardW - 0.3, h: 1.5, valign: "top", margin: 0 });

    // Bottom callout
    slide.addShape(pres.shapes.RECTANGLE, {
      x: 0.6, y: 4.4, w: 8.8, h: 0.7,
      fill: { color: C.darkBg }, rectRadius: 0.08
    });
    slide.addText([
      { text: "Humans possess situational self-awareness ", options: { bold: true, color: C.amber, fontSize: 12 } },
      { text: "— the metacognitive ability to assess whether they can handle a situation directly, need to reflect, or must seek external help. KnowSelf brings this to LLM agents.", options: { color: C.whiteText, fontSize: 11 } }
    ], { x: 0.85, y: 4.45, w: 8.3, h: 0.6, valign: "middle", margin: 0 });
  }

  // ========================================================
  // SLIDE 3: Three Thinking Modes — redesigned as 3-column cards with flow indicators
  // ========================================================
  {
    const slide = pres.addSlide();
    slide.background = { color: C.lightBg };

    slide.addShape(pres.shapes.RECTANGLE, {
      x: 0, y: 0, w: 10, h: 0.9, fill: { color: C.darkBg }
    });
    slide.addText("Three Situational Modes", {
      x: 0.6, y: 0.12, w: 7, h: 0.65,
      fontSize: 24, fontFace: "Arial Black", color: C.whiteText, bold: true, margin: 0
    });
    slide.addText("Fast Thinking · Slow Thinking · Knowledgeable Thinking", {
      x: 0.6, y: 0.52, w: 7, h: 0.35,
      fontSize: 12, fontFace: "Calibri", color: C.skyBlue, margin: 0
    });

    // Decision flow: compact question bar across top
    const flowY = 1.1;
    const flowH = 0.45;
    slide.addShape(pres.shapes.RECTANGLE, {
      x: 0.6, y: flowY, w: 8.8, h: flowH,
      fill: { color: C.darkBg2 }, rectRadius: 0.06
    });
    slide.addText([
      { text: "Decision Criterion:  ", options: { bold: true, color: C.amber, fontSize: 11 } },
      { text: "Predicted = Gold?  →  Fast   |   Reflection fixes?  →  Slow   |   Neither?  →  Knowledgeable", options: { color: C.whiteText, fontSize: 11 } }
    ], { x: 0.85, y: flowY, w: 8.3, h: flowH, valign: "middle", margin: 0 });

    // Three mode cards — sized to fit within slide with 0.5" margins
    const cardW = 2.7;
    const cardH = 3.3;
    const gap = 0.35;
    const totalW = 3 * cardW + 2 * gap;
    const startX = (10 - totalW) / 2;
    const cardY = 1.75;

    // Fast Thinking
    const fx = startX;
    slide.addShape(pres.shapes.RECTANGLE, { x: fx, y: cardY, w: cardW, h: cardH, fill: { color: C.cardWhite }, shadow: makeShadow() });
    slide.addShape(pres.shapes.RECTANGLE, { x: fx, y: cardY, w: cardW, h: 0.06, fill: { color: C.skyBlue } });
    slide.addImage({ data: iconBolt, x: fx + 0.15, y: cardY + 0.15, w: 0.4, h: 0.4 });
    slide.addText("Fast Thinking", {
      x: fx + 0.6, y: cardY + 0.2, w: 1.95, h: 0.3,
      fontSize: 16, fontFace: "Calibri", color: C.skyBlue, bold: true, margin: 0
    });
    slide.addText([
      { text: "Criterion", options: { breakLine: true, fontSize: 11, color: C.mutedText, bold: true } },
      { text: "Predicted action matches gold action on first attempt", options: { breakLine: true, fontSize: 11, color: C.darkText } },
      { text: "", options: { breakLine: true, fontSize: 6 } },
      { text: "Behavior", options: { breakLine: true, fontSize: 11, color: C.mutedText, bold: true } },
      { text: "Agent directly produces the correct action with minimal deliberation", options: { breakLine: true, fontSize: 11, color: C.darkText } },
      { text: "", options: { breakLine: true, fontSize: 6 } },
      { text: "Token", options: { breakLine: true, fontSize: 11, color: C.mutedText, bold: true } },
      { text: "No special token needed — direct action output", options: { fontSize: 11, color: C.darkText } }
    ], { x: fx + 0.15, y: cardY + 0.65, w: cardW - 0.3, h: 2.5, valign: "top", margin: 0 });

    // Slow Thinking
    const sx = startX + cardW + gap;
    slide.addShape(pres.shapes.RECTANGLE, { x: sx, y: cardY, w: cardW, h: cardH, fill: { color: C.cardWhite }, shadow: makeShadow() });
    slide.addShape(pres.shapes.RECTANGLE, { x: sx, y: cardY, w: cardW, h: 0.06, fill: { color: C.violet } });
    slide.addImage({ data: iconBrain, x: sx + 0.15, y: cardY + 0.15, w: 0.4, h: 0.4 });
    slide.addText("Slow Thinking", {
      x: sx + 0.6, y: cardY + 0.2, w: 1.95, h: 0.3,
      fontSize: 16, fontFace: "Calibri", color: C.violet, bold: true, margin: 0
    });
    slide.addText([
      { text: "Criterion", options: { breakLine: true, fontSize: 11, color: C.mutedText, bold: true } },
      { text: "Initial action is wrong, but self-reflection corrects it", options: { breakLine: true, fontSize: 11, color: C.darkText } },
      { text: "", options: { breakLine: true, fontSize: 6 } },
      { text: "Behavior", options: { breakLine: true, fontSize: 11, color: C.mutedText, bold: true } },
      { text: "Agent pauses to reflect and self-correct before acting", options: { breakLine: true, fontSize: 11, color: C.darkText } },
      { text: "", options: { breakLine: true, fontSize: 6 } },
      { text: "Token", options: { breakLine: true, fontSize: 11, color: C.mutedText, bold: true } },
      { text: "Generates Reflection token → triggers self-correction", options: { fontSize: 11, color: C.darkText } }
    ], { x: sx + 0.15, y: cardY + 0.65, w: cardW - 0.3, h: 2.5, valign: "top", margin: 0 });

    // Knowledgeable Thinking
    const kx = startX + 2 * (cardW + gap);
    slide.addShape(pres.shapes.RECTANGLE, { x: kx, y: cardY, w: cardW, h: cardH, fill: { color: C.cardWhite }, shadow: makeShadow() });
    slide.addShape(pres.shapes.RECTANGLE, { x: kx, y: cardY, w: cardW, h: 0.06, fill: { color: C.orange } });
    slide.addImage({ data: iconBook, x: kx + 0.15, y: cardY + 0.15, w: 0.4, h: 0.4 });
    slide.addText("Knowledgeable Thinking", {
      x: kx + 0.6, y: cardY + 0.2, w: 1.95, h: 0.3,
      fontSize: 15, fontFace: "Calibri", color: C.orange, bold: true, margin: 0
    });
    slide.addText([
      { text: "Criterion", options: { breakLine: true, fontSize: 11, color: C.mutedText, bold: true } },
      { text: "Agent cannot produce correct action even after reflection", options: { breakLine: true, fontSize: 11, color: C.darkText } },
      { text: "", options: { breakLine: true, fontSize: 6 } },
      { text: "Behavior", options: { breakLine: true, fontSize: 11, color: C.mutedText, bold: true } },
      { text: "Agent consults external knowledge base for guidance", options: { breakLine: true, fontSize: 11, color: C.darkText } },
      { text: "", options: { breakLine: true, fontSize: 6 } },
      { text: "Token", options: { breakLine: true, fontSize: 11, color: C.mutedText, bold: true } },
      { text: "Generates Knowledge token → triggers external KB retrieval", options: { fontSize: 11, color: C.darkText } }
    ], { x: kx + 0.15, y: cardY + 0.65, w: cardW - 0.3, h: 2.5, valign: "top", margin: 0 });
  }

  // ========================================================
  // SLIDE 4: KnowSelf Framework Pipeline
  // ========================================================
  {
    const slide = pres.addSlide();
    slide.background = { color: C.lightBg };

    slide.addShape(pres.shapes.RECTANGLE, {
      x: 0, y: 0, w: 10, h: 0.9, fill: { color: C.darkBg }
    });
    slide.addText("KnowSelf Framework", {
      x: 0.6, y: 0.12, w: 7, h: 0.65,
      fontSize: 24, fontFace: "Arial Black", color: C.whiteText, bold: true, margin: 0
    });
    slide.addText("Data Construction → Two-Stage Training → Self-Aware Inference", {
      x: 0.6, y: 0.52, w: 7, h: 0.35,
      fontSize: 12, fontFace: "Calibri", color: C.skyBlue, margin: 0
